diffs.patch:
Index: src/canary.test.ts
===================================================================
--- src/canary.test.ts	
+++ src/canary.test.ts	
@@ -0,0 +1,14 @@
+import { expect, test } from "bun:test";
+import { canary, canaryGreeting } from "./canary";
+
+test("canary remains exported", () => {
+  expect(canary).toBe(true);
+});
+
+test("greets Ada", () => {
+  expect(canaryGreeting("Ada")).toBe("Hello, Ada!");
+});
+
+test("greets an empty name", () => {
+  expect(canaryGreeting("")).toBe("Hello, !");
+});

Index: src/canary.ts
===================================================================
--- src/canary.ts	
+++ src/canary.ts	
@@ -1,1 +1,5 @@
 export const canary = true;
+
+export function canaryGreeting(name: string): string {
+  return `Hello, ${name}!`;
+}

